def _enable_timescale() -> None:
    """Promote ``price_bars`` to a Timescale hypertable where the extension exists.

    Local development and CI commonly use stock PostgreSQL, so this is a guarded
    no-op there rather than a hard dependency. The primary key already includes
    the partitioning column, as Timescale requires.
    """
    bind = op.get_bind()
    if bind.dialect.name != "postgresql":
        return
    available = bind.execute(
        sa.text("SELECT 1 FROM pg_available_extensions WHERE name = 'timescaledb'")
    ).scalar()
    if not available:
        return
    op.execute("CREATE EXTENSION IF NOT EXISTS timescaledb")
    op.execute(
        "SELECT create_hypertable('price_bars', 'ts', if_not_exists => TRUE, migrate_data => TRUE)"
    )


